 const rangedRows=analysisRangeRows(viewRows,analysisRangeMode,customAnalysisCount),analysisRows=similarOnly?comparableSubset(rangedRows):rangedRows,compareRows=compareEnabled?comparisonRows(viewRows,analysisRows,compareMode,customCompareCount):[],selectedRun=analyzed.find(r=>r.id===selectedRunId)||null;
 const analysisCombined=combineAerobicFitness(analyzed.map(r=>({...r,included:analysisRows.some(a=>a.id===r.id)&&r.runType==='treadmill'})));
 const analysisRangeLabel=analysisRangeMode==='all'?'All selected runs':analysisRangeMode==='last5'?'Last 5 runs':analysisRangeMode==='last10'?'Last 10 runs':analysisRangeMode==='30d'?'Last 30 days':analysisRangeMode==='firstcustom'?`First ${Math.min(Number(customAnalysisCount)||5,viewRows.length)} runs`:`Last ${Math.min(Number(customAnalysisCount)||10,viewRows.length)} runs`;
