function ExpMetric({name,abbr,value,sub,confidence,children}){return <article className="exp-card"><div className="exp-card-head"><div><span>{abbr}</span><h3>{name}</h3></div><em className={'exp-confidence '+String(confidence||'').toLowerCase()}>{confidence||'Unavailable'} confidence</em></div><strong className="exp-value">{value}</strong>{sub&&<p className="exp-sub">{sub}</p>}{children}</article>}
function ExpTrend({title,rows,get,fmt}){
 const pts=rows.map((r,i)=>({i,v:get(r),label:r.dateLabel})).filter(p=>Number.isFinite(p.v));if(pts.length<2)return <div className="exp-trend-empty"><b>{title}</b><span>Needs at least 2 qualifying runs.</span></div>;
 const W=640,H=210,L=50,R=18,T=20,B=38,vals=pts.map(p=>p.v),lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max((hi-lo)*.12,Math.abs(hi||1)*.02,.01),mn=lo-pad,mx=hi+pad,x=i=>L+(i/Math.max(1,rows.length-1))*(W-L-R),y=v=>H-B-(v-mn)/Math.max(.0001,mx-mn)*(H-T-B);
 const path=pts.map((p,j)=>(j?'L':'M')+x(p.i)+' '+y(p.v)).join(' ');
 return <div className="exp-trend"><div className="viz-head"><div><span>LONGITUDINAL</span><strong>{title}</strong></div><small>qualifying n={pts.length}</small></div><svg viewBox={`0 0 ${W} ${H}`}><line className="chart-axis" x1={L} y1={H-B} x2={W-R} y2={H-B}/><path className="exp-trend-line" d={path}/>{pts.map((p,j)=><g key={j}><circle className="exp-trend-point" cx={x(p.i)} cy={y(p.v)} r="5"/><title>{p.label}: {fmt(p.v)}</title></g>)}<text className="chart-text tick-label" x={L} y={H-12}>{rows[0]?.dateLabel}</text><text className="chart-text tick-label" x={W-R} y={H-12} textAnchor="end">{rows.at(-1)?.dateLabel}</text><text className="chart-text tick-label" x={L-7} y={y(hi)+4} textAnchor="end">{fmt(hi)}</text><text className="chart-text tick-label" x={L-7} y={y(lo)+4} textAnchor="end">{fmt(lo)}</text></svg></div>
}
function MiniChartFrame({eyebrow,title,note,children}){return <div className="exp-detail-chart"><div className="viz-head"><div><span>{eyebrow}</span><strong>{title}</strong></div></div>{children}<p className="viz-note">{note}</p></div>}
function DurabilityChart({exp}){const a=exp.series||[];if(a.length<2)return null;const W=760,H=250,L=52,R=18,T=18,B=38,start=a[0].t,end=a.at(-1).t,vals=a.map(r=>r.ef),lo=Math.min(...vals),hi=Math.max(...vals),pad=(hi-lo||hi*.05||.01)*.08,x=t=>L+(t-start)/(end-start)*(W-L-R),y=v=>H-B-(v-(lo-pad))/((hi+pad)-(lo-pad))*(H-T-B),path=a.map((r,i)=>(i?'L':'M')+x(r.t)+' '+y(r.ef)).join(' '),q=t=>start+t*(end-start);return <MiniChartFrame eyebrow="EFFICIENCY PROFILE" title="Durability across the run" note="Shaded windows are the early (20–40%) and late (60–80%) comparison periods used by DI. The line is speed ÷ heart rate at 5-second resolution."><svg viewBox={`0 0 ${W} ${H}`}><rect className="exp-window early" x={x(q(.2))} y={T} width={x(q(.4))-x(q(.2))} height={H-T-B}/><rect className="exp-window late" x={x(q(.6))} y={T} width={x(q(.8))-x(q(.6))} height={H-T-B}/><line className="chart-axis" x1={L} y1={H-B} x2={W-R} y2={H-B}/><path className="exp-detail-line" d={path}/><text className="chart-text tick-label" x={x(q(.3))} y={T+14} textAnchor="middle">EARLY</text><text className="chart-text tick-label" x={x(q(.7))} y={T+14} textAnchor="middle">LATE</text><text className="chart-text tick-label" x={L} y={H-12}>0%</text><text className="chart-text tick-label" x={W-R} y={H-12} textAnchor="end">100% of run</text></svg></MiniChartFrame>}
function FipChart({exp}){const a=exp.series||[],f=exp.fip;if(a.length<2)return null;const W=760,H=250,L=52,R=18,T=18,B=38,start=a[0].t,end=a.at(-1).t,vals=a.map(r=>r.ef),lo=Math.min(...vals),hi=Math.max(...vals),pad=(hi-lo||.01)*.08,x=t=>L+(t-start)/(end-start)*(W-L-R),y=v=>H-B-(v-(lo-pad))/((hi+pad)-(lo-pad))*(H-T-B),path=a.map((r,i)=>(i?'L':'M')+x(r.t)+' '+y(r.ef)).join(' '),ft=f?start+f.timeS:null;return <MiniChartFrame eyebrow="BREAKPOINT VIEW" title="Fatigue inflection" note={f?'The vertical marker is the detected fatigue-onset point. It may come from segmented regression or a sustained-loss test against the run’s early efficiency baseline. The shaded region shows the portion after detection.':'No supported breakpoint was detected, so the chart shows the efficiency profile without forcing an inflection.'}><svg viewBox={`0 0 ${W} ${H}`}>{f&&<rect className="exp-post-region" x={x(ft)} y={T} width={W-R-x(ft)} height={H-T-B}/>}<line className="chart-axis" x1={L} y1={H-B} x2={W-R} y2={H-B}/><path className="exp-detail-line" d={path}/>{f&&<><line className="exp-fip-line" x1={x(ft)} y1={T} x2={x(ft)} y2={H-B}/><text className="chart-text exp-fip-label" x={Math.min(x(ft)+7,W-110)} y={T+16}>FIP {f.pct.toFixed(0)}%</text></>}<text className="chart-text tick-label" x={L} y={H-12}>Start</text><text className="chart-text tick-label" x={W-R} y={H-12} textAnchor="end">End</text></svg></MiniChartFrame>}
function HysteresisChart({exp}){const a=exp.series||[];if(a.length<2)return null;const W=760,H=280,L=56,R=22,T=18,B=42,s=a.map(r=>r.speed),h=a.map(r=>r.hr),s0=Math.min(...s),s1=Math.max(...s),h0=Math.min(...h),h1=Math.max(...h),x=v=>L+(v-s0)/Math.max(.001,s1-s0)*(W-L-R),y=v=>H-B-(v-h0)/Math.max(.001,h1-h0)*(H-T-B),path=a.map((r,i)=>(i?'L':'M')+x(r.speed)+' '+y(r.hr)).join(' '),marks=[.2,.4,.6,.8].map(f=>a[Math.min(a.length-1,Math.floor(f*(a.length-1)))]);return <MiniChartFrame eyebrow="RESPONSE LOOP" title="Pace–HR hysteresis trajectory" note="The connected path follows the run chronologically through speed–heart-rate space. Numbered markers show progression through the activity; larger loop behavior contributes to PHH."><svg viewBox={`0 0 ${W} ${H}`}><line className="chart-axis" x1={L} y1={H-B} x2={W-R} y2={H-B}/><line className="chart-axis" x1={L} y1={T} x2={L} y2={H-B}/><path className="exp-loop-line" d={path}/>{marks.map((r,i)=><g key={i}><circle className="exp-loop-mark" cx={x(r.speed)} cy={y(r.hr)} r="9"/><text className="chart-text exp-loop-num" x={x(r.speed)} y={y(r.hr)+3} textAnchor="middle">{i+1}</text></g>)}<text className="chart-text tick-label" x={(L+W-R)/2} y={H-9} textAnchor="middle">Speed (mph)</text><text className="chart-text tick-label" transform={`translate(14 ${(T+H-B)/2}) rotate(-90)`} textAnchor="middle">Heart rate (bpm)</text><text className="chart-text tick-label" x={L} y={H-B+18}>{s0.toFixed(1)}</text><text className="chart-text tick-label" x={W-R} y={H-B+18} textAnchor="end">{s1.toFixed(1)}</text></svg></MiniChartFrame>}
function LagChart({exp}){const a=exp.series||[],lag=exp.arl?.seconds;if(a.length<2)return null;const W=760,H=286,L=52,R=18,T=42,B=38,start=a[0].t,end=a.at(-1).t,sp=a.map(r=>r.speed),hr=a.map(r=>r.hr),norm=(v,lo,hi)=>100*(v-lo)/Math.max(.001,hi-lo),s0=Math.min(...sp),s1=Math.max(...sp),h0=Math.min(...hr),h1=Math.max(...hr),x=t=>L+(t-start)/(end-start)*(W-L-R),y=v=>H-B-v/100*(H-T-B),p1=a.map((r,i)=>(i?'L':'M')+x(r.t)+' '+y(norm(r.speed,s0,s1))).join(' '),p2=a.map((r,i)=>(i?'L':'M')+x(r.t)+' '+y(norm(r.hr,h0,h1))).join(' ');return <MiniChartFrame eyebrow="RESPONSE TIMING" title="Running demand vs heart-rate response" note={Number.isFinite(lag)?`Both signals are normalized to their own activity ranges so timing can be compared visually. Estimated response lag: ${lag} seconds.`:'Signals are normalized to their own ranges. No reliable response lag was resolved for this activity.'}><svg viewBox={`0 0 ${W} ${H}`}><line className="chart-axis" x1={L} y1={H-B} x2={W-R} y2={H-B}/><path className="exp-speed-line" d={p1}/><path className="exp-hr-line" d={p2}/><g className="exp-legend"><rect className="exp-legend-bg" x={W-230} y="6" width="210" height="28" rx="6"/><line className="exp-speed-line" x1={W-215} y1="20" x2={W-187} y2="20"/><text className="chart-text" x={W-180} y="24">Speed</text><line className="exp-hr-line" x1={W-112} y1="20" x2={W-84} y2="20"/><text className="chart-text" x={W-77} y="24">HR</text></g><text className="chart-text tick-label" x={L} y={H-12}>Start</text><text className="chart-text tick-label" x={W-R} y={H-12} textAnchor="end">End</text></svg></MiniChartFrame>}
function RecoveryChart({exp}){const ev=exp.recovery?.events||[];if(!ev.length)return <MiniChartFrame eyebrow="RECOVERY CURVES" title="Post-effort heart-rate recovery" note="No qualifying recovery event was detected in this activity."><div className="exp-chart-empty">No qualifying recovery curve to plot.</div></MiniChartFrame>;const W=760,H=270,L=52,R=18,T=18,B=40,maxT=Math.max(60,...ev.flatMap(e=>(e.curve||[]).map(p=>p.t))),minRel=Math.min(-5,...ev.flatMap(e=>(e.curve||[]).map(p=>p.relative))),x=t=>L+t/maxT*(W-L-R),y=v=>T+(0-v)/(0-minRel)*(H-T-B);return <MiniChartFrame eyebrow="RECOVERY CURVES" title="Post-effort heart-rate decay" note="Each line begins at a detected local HR peak and shows change from that peak. Curves ending farther below zero represent larger HR reductions; τ summarizes decay speed."><svg viewBox={`0 0 ${W} ${H}`}><line className="chart-axis" x1={L} y1={y(0)} x2={W-R} y2={y(0)}/>{ev.map((e,k)=>{const c=e.curve||[],d=c.map((p,i)=>(i?'L':'M')+x(p.t)+' '+y(p.relative)).join(' ');return <path key={k} className={'exp-recovery-line r'+(k%5)} d={d}><title>Recovery {k+1}: HRR60 {e.hrr60.toFixed(0)} bpm, τ {e.tau.toFixed(0)} s</title></path>})}<text className="chart-text tick-label" x={L} y={H-10}>0 sec</text><text className="chart-text tick-label" x={W-R} y={H-10} textAnchor="end">{Math.round(maxT)} sec</text><text className="chart-text tick-label" x={L-7} y={y(0)+4} textAnchor="end">0</text><text className="chart-text tick-label" x={L-7} y={y(minRel)+4} textAnchor="end">{Math.round(minRel)} bpm</text></svg></MiniChartFrame>}
function ExperimentalCharts({exp}){return <section className="exp-chart-section"><div className="exp-results-head"><div><div className="eyebrow">VISUAL DIAGNOSTICS</div><h2>See what the metrics are measuring</h2></div><p>Charts use the same normalized record-level data as the experimental calculations.</p></div><div className="exp-chart-grid"><DurabilityChart exp={exp}/><FipChart exp={exp}/><HysteresisChart exp={exp}/><LagChart exp={exp}/><RecoveryChart exp={exp}/></div></section>}

function Experimental(){
 const[mode,setMode]=useState('single');
 const[file,setFile]=useState(null),[activity,setActivity]=useState(null),[error,setError]=useState('');
 const[distance,setDistance]=useState(''),[time,setTime]=useState(''),[runType,setRunType]=useState('outdoor');
 const[multiRuns,setMultiRuns]=useState([]),[multiFilter,setMultiFilter]=useState('all'),[multiError,setMultiError]=useState('');
 const load=async(files)=>{const f=files[0];if(!f)return;setError('');try{const a=await importActivity(f),det=inferRunType(a);setFile(f);setActivity(a);setRunType(det.type);setDistance(Number.isFinite(safeMiles(a))?safeMiles(a).toFixed(3):'');setTime(Number.isFinite(safeTime(a))?formatDuration(safeTime(a)):'')}catch(e){setError(e.message||String(e));setActivity(null)}};
 const loadMulti=async(files)=>{setMultiError('');const out=[];for(const f of files){try{const a=await importActivity(f),det=inferRunType(a),m=safeMiles(a),sec=safeTime(a);const an=analyzeTreadmillActivity(a,{targetDistanceM:Number.isFinite(m)?m*1609.344:NaN,targetTimerS:sec});const exp=experimentalMetrics(an);const ts=(a.records||[]).map(r=>r.timestampMs).find(Number.isFinite);out.push({id:`${f.name}-${f.size}-${f.lastModified}`,name:f.name,activity:a,runType:det.type,analysis:an,exp,timestamp:Number.isFinite(ts)?ts:f.lastModified})}catch(e){setMultiError(v=>v+(v?'\n':'')+f.name+': '+(e.message||String(e)))}}setMultiRuns(cur=>{const ids=new Set(cur.map(r=>r.id));return [...cur,...out.filter(r=>!ids.has(r.id))].sort((a,b)=>a.timestamp-b.timestamp)})};
 const analysis=useMemo(()=>{if(!activity)return null;const treadmill=runType==='treadmill',miles=treadmill?Number(distance):safeMiles(activity),seconds=treadmill?parseClock(time):safeTime(activity);return analyzeTreadmillActivity(activity,{targetDistanceM:miles>0?miles*1609.344:NaN,targetTimerS:seconds})},[activity,runType,distance,time]);
 const exp=useMemo(()=>experimentalMetrics(analysis),[analysis]);
 const clock=s=>Number.isFinite(s)?formatDuration(s):'—';
 const multiRows=useMemo(()=>multiRuns.filter(r=>multiFilter==='all'||r.runType===multiFilter).map((r,i)=>({...r,runIndex:i,dateLabel:Number.isFinite(r.timestamp)?new Date(r.timestamp).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'2-digit'}):`Run ${i+1}`})),[multiRuns,multiFilter]);
 const qualifying=multiRows.filter(r=>r.exp?.available),counts={all:multiRuns.length,treadmill:multiRuns.filter(r=>r.runType==='treadmill').length,outdoor:multiRuns.filter(r=>r.runType==='outdoor').length};
 return <><section className="hero exp-hero"><div className="eyebrow">ENDURANCE FORGE LAB</div><h1>Experimental metrics.</h1><p>Useful, less-established ways to examine durability, fatigue, cardiovascular response, and recovery. These metrics are exploratory analytics — not clinical measures, device-manufacturer metrics, or universal performance scores.</p><div className="exp-badges"><span>EXPERIMENTAL</span><span>PERSONAL CONTEXT</span><span>CONFIDENCE-GATED</span></div><p className="exp-method-link"><a className="doc-link" href="/methodology/#experimental-methodology">Read the equations, detection rules, confidence logic, and limitations →</a></p></section>
 <div className="exp-mode-tabs"><button className={mode==='single'?'active':''} onClick={()=>setMode('single')}>Single Run</button><button className={mode==='multi'?'active':''} onClick={()=>setMode('multi')}>Multi-Run</button></div>
 {mode==='single'?<>
 <section className="panel exp-upload"><div className="panel-head"><div><span>01</span><h2>Analyze an activity</h2></div><small>FIT · TCX · GPX processed locally</small></div><DropZone onFiles={load} title="Drop a run here for experimental analysis"/>{error&&<p className="error">{error}</p>}{activity&&<><div className="exp-run-row"><div><b>{file?.name}</b><span>{runType==='treadmill'?'Treadmill':'Outdoor'} · {Number.isFinite(safeMiles(activity))?safeMiles(activity).toFixed(2)+' mi':'distance unavailable'}</span></div><div className="exp-type-toggle"><button className={runType==='outdoor'?'active':''} onClick={()=>setRunType('outdoor')}>Outdoor</button><button className={runType==='treadmill'?'active':''} onClick={()=>setRunType('treadmill')}>Treadmill</button></div></div>{runType==='treadmill'&&<div className="form-grid exp-truth"><label>Treadmill distance (miles)<input value={distance} onChange={e=>setDistance(e.target.value)}/></label><label>Treadmill time<input value={time} onChange={e=>setTime(e.target.value)}/></label></div>}</>}</section>
 {!activity?<section className="exp-intro"><h2>The first five experiments</h2><div className="exp-definition-grid">{[['DI','Durability Index','How much running efficiency is retained later in the run.'],['FIP','Fatigue Inflection Point','When efficiency begins a sustained deterioration.'],['PHH','Pace–HR Hysteresis','How differently heart rate behaves as running demand rises and falls.'],['ARL','Aerobic Response Lag','How long heart-rate response trails changes in running demand.'],['RK','Recovery Kinetics','How quickly heart rate falls after meaningful efforts.']].map(x=><article key={x[0]}><span>{x[0]}</span><h3>{x[1]}</h3><p>{x[2]}</p></article>)}</div></section>:
 !exp?.available?<section className="panel exp-pending"><h2>Experimental analysis unavailable</h2><p>{exp?.reason||'This activity does not contain enough usable time-series data.'}</p></section>:
 <section className="exp-results"><div className="exp-results-head"><div><div className="eyebrow">EXPERIMENTAL ANALYTICS v1</div><h2>Five views of the same physiological story</h2></div><p>{clock(exp.durationS)} analyzed · {exp.samples} normalized samples</p></div><div className="exp-grid">
 <ExpMetric name="Durability Index" abbr="DI" confidence={exp.durability.confidence} value={Number.isFinite(exp.durability.value)?exp.durability.value.toFixed(1)+'%':'—'} sub={Number.isFinite(exp.durability.loss)?`${exp.durability.loss>=0?exp.durability.loss.toFixed(1)+'% efficiency loss':Math.abs(exp.durability.loss).toFixed(1)+'% efficiency gain'} from early to late comparison windows.`:'Insufficient comparable windows.'}><p>Compares speed-per-heartbeat efficiency in the 20–40% and 60–80% portions of the analyzed run. It is a retention measure, not a universal score.</p></ExpMetric>
 <ExpMetric name="Fatigue Inflection Point" abbr="FIP" confidence={exp.fip?.confidence} value={exp.fip?clock(exp.fip.timeS):'Not detected'} sub={exp.fip?`${exp.fip.pct.toFixed(0)}% into the analyzed run · ${exp.fip.method==='change-point'?'change point':'progressive onset'}${Number.isFinite(exp.fip.declinePctHr)?` · subsequent trend ${exp.fip.declinePctHr.toFixed(1)}%/hr`:''}${Number.isFinite(exp.fip.deltaBic)?` · ΔBIC ${exp.fip.deltaBic.toFixed(1)}`:''}.`:'No supported change point or progressive onset was found.'}><p>FIP uses two validation paths: a discrete segmented-regression change point or a sustained progressive onset. The progressive path uses an adaptive loss threshold and persistence test rather than a fixed percent-of-run trigger.</p>{exp.fipDiagnostics&&<details className="exp-diagnostics"><summary>FIP validation diagnostics</summary><div><b>Status:</b> {exp.fipDiagnostics.status}</div><div><b>Method:</b> {exp.fipDiagnostics.method}</div><div><b>Change-point candidate:</b> {Number.isFinite(exp.fipDiagnostics.candidatePct)?exp.fipDiagnostics.candidatePct.toFixed(0)+'%':'—'}</div><div><b>Progressive candidate:</b> {Number.isFinite(exp.fipDiagnostics.progressiveCandidatePct)?exp.fipDiagnostics.progressiveCandidatePct.toFixed(0)+'%':'—'}</div><div><b>ΔBIC:</b> {Number.isFinite(exp.fipDiagnostics.deltaBic)?exp.fipDiagnostics.deltaBic.toFixed(1):'—'}</div><div><b>Early-to-late loss:</b> {Number.isFinite(exp.fipDiagnostics.overallLossPct)?exp.fipDiagnostics.overallLossPct.toFixed(1)+'%':'—'}</div><div><b>Progressive threshold / persistence:</b> {Number.isFinite(exp.fipDiagnostics.progressiveThresholdPct)?exp.fipDiagnostics.progressiveThresholdPct.toFixed(1)+'%':'—'} / {Number.isFinite(exp.fipDiagnostics.progressivePersistence)?(exp.fipDiagnostics.progressivePersistence*100).toFixed(0)+'%':'—'}</div><div><b>Pre / post slope:</b> {Number.isFinite(exp.fipDiagnostics.preSlopePctHr)?exp.fipDiagnostics.preSlopePctHr.toFixed(2)+'%/hr':'—'} / {Number.isFinite(exp.fipDiagnostics.postSlopePctHr)?exp.fipDiagnostics.postSlopePctHr.toFixed(2)+'%/hr':'—'}</div><ul>{exp.fipDiagnostics.reasons.map((r,i)=><li key={i}>{r}</li>)}</ul></details>}</ExpMetric>
 <ExpMetric name="Pace–HR Hysteresis" abbr="PHH" confidence={exp.hysteresis.confidence} value={Number.isFinite(exp.hysteresis.value)?exp.hysteresis.value.toFixed(2):'Unavailable'} sub={Number.isFinite(exp.hysteresis.value)?`Normalized loop magnitude · ${exp.hysteresis.variationMph.toFixed(2)} mph central speed range.`:'The run did not contain enough intensity variation.'}><p>Measures the normalized area traced by speed and heart rate as workload changes. It is most informative in runs with meaningful accelerations and decelerations.</p></ExpMetric>
 <ExpMetric name="Aerobic Response Lag" abbr="ARL" confidence={exp.arl?.confidence} value={exp.arl?exp.arl.seconds+' sec':'Unavailable'} sub={exp.arl?`Peak change-to-change correlation r=${exp.arl.correlation.toFixed(2)}.`:'No reliable lag could be resolved from this activity.'}><p>Estimates the delay between changes in running speed and subsequent heart-rate response. Low workload variation or noisy sensor data can make the estimate unavailable.</p></ExpMetric>
 <ExpMetric name="Recovery Kinetics" abbr="RK" confidence={exp.recovery?.confidence} value={exp.recovery?`τ ${exp.recovery.tau.toFixed(0)} sec`:'No recovery detected'} sub={exp.recovery?`Median HRR60 ${exp.recovery.hrr60.toFixed(0)} bpm across ${exp.recovery.count} detected ${exp.recovery.count===1?'recovery':'recoveries'}.`:'No post-effort recovery met the current detection requirements.'}><p>Fits the heart-rate decay after detected efforts. The time constant τ describes the recovery curve; smaller values represent faster decay within this model.</p></ExpMetric>
 </div><ExperimentalCharts exp={exp}/><div className="exp-caution"><b>How to use Experimental</b><p>Look for repeatable within-person patterns across comparable runs. Do not treat a single value as a diagnosis or a universal good/bad threshold. Algorithms and thresholds may change as Endurance Forge validates these measures against more activities.</p></div></section>}
 </>:<section className="exp-multi"><div className="panel exp-upload"><div className="panel-head"><div><span>01</span><h2>Load runs for longitudinal Experimental analysis</h2></div><small>Multiple FIT · TCX · GPX files</small></div><DropZone multiple onFiles={loadMulti} title={multiRuns.length?'Add more activities':'Drop several activities here'}/>{multiError&&<p className="error">{multiError}</p>}{multiRuns.length>0&&<><div className="heat-filter dashboard-filter"><div><b>Run type</b><span>Treadmill and outdoor runs can have different baselines; filter them rather than assuming they are interchangeable.</span></div><div>{['all','treadmill','outdoor'].map(x=><button key={x} className={multiFilter===x?'active':''} onClick={()=>setMultiFilter(x)}>{x==='all'?'All Runs':x==='treadmill'?'Treadmill':'Outdoor'} <small>{counts[x]}</small></button>)}</div></div><div className="exp-multi-summary"><Metric label="Loaded" value={String(multiRows.length)} sub="runs in current view"/><Metric label="Qualifying" value={String(qualifying.length)} sub="experimental analysis available"/><Metric label="DI available" value={String(qualifying.filter(r=>Number.isFinite(r.exp?.durability?.value)).length)} sub="durability observations"/><Metric label="FIP detected" value={String(qualifying.filter(r=>r.exp?.fip).length)} sub="supported breakpoints"/><Metric label="Recovery detected" value={String(qualifying.filter(r=>r.exp?.recovery).length)} sub="runs with qualifying recovery"/></div></>}</div>
 {multiRuns.length===0?<section className="exp-intro"><h2>Why multi-run matters</h2><p className="note">A single experimental value is descriptive. Repeated comparable observations let Endurance Forge ask whether durability, fatigue onset, response lag, hysteresis, or recovery behavior is changing over time.</p></section>:qualifying.length<2?<div className="panel exp-pending"><h2>More qualifying runs needed</h2><p>At least two activities in the current view must contain sufficient record-level speed and heart-rate data before longitudinal charts are shown.</p></div>:<><div className="exp-trend-grid"><ExpTrend title="Durability Index" rows={qualifying} get={r=>r.exp?.durability?.value} fmt={v=>v.toFixed(1)+'%'}/><ExpTrend title="Fatigue Inflection (% of run)" rows={qualifying} get={r=>r.exp?.fip?.pct} fmt={v=>v.toFixed(0)+'%'}/><ExpTrend title="Pace–HR Hysteresis" rows={qualifying} get={r=>r.exp?.hysteresis?.value} fmt={v=>v.toFixed(2)}/><ExpTrend title="Aerobic Response Lag" rows={qualifying} get={r=>r.exp?.arl?.seconds} fmt={v=>v.toFixed(0)+' s'}/><ExpTrend title="Recovery Time Constant τ" rows={qualifying} get={r=>r.exp?.recovery?.tau} fmt={v=>v.toFixed(0)+' s'}/></div><div className="panel exp-table-panel"><div className="panel-head"><div><span>RUN DETAIL</span><h2>Experimental results by activity</h2></div><small>— means metric unavailable/not detected</small></div><div className="table-wrap"><table><thead><tr><th>Date</th><th>Run</th><th>Type</th><th>DI</th><th>FIP</th><th>FIP method</th><th>ΔBIC</th><th>PHH</th><th>ARL</th><th>Recovery τ</th></tr></thead><tbody>{multiRows.map(r=><tr key={r.id}><td>{r.dateLabel}</td><td title={r.name}>{r.name}</td><td>{r.runType}</td><td>{Number.isFinite(r.exp?.durability?.value)?r.exp.durability.value.toFixed(1)+'%':'—'}</td><td>{r.exp?.fip?r.exp.fip.pct.toFixed(0)+'%':'—'}</td><td>{r.exp?.fip?(r.exp.fip.method==='change-point'?'change point':'progressive onset'):(Number.isFinite(r.exp?.fipDiagnostics?.overallLossPct)&&r.exp.fipDiagnostics.overallLossPct>=3?'progressive, no onset':'—')}</td><td>{Number.isFinite(r.exp?.fipDiagnostics?.deltaBic)?r.exp.fipDiagnostics.deltaBic.toFixed(1):'—'}</td><td>{Number.isFinite(r.exp?.hysteresis?.value)?r.exp.hysteresis.value.toFixed(2):'—'}</td><td>{r.exp?.arl?r.exp.arl.seconds+' s':'—'}</td><td>{r.exp?.recovery?r.exp.recovery.tau.toFixed(0)+' s':'—'}</td></tr>)}</tbody></table></div></div><div className="exp-caution"><b>Longitudinal interpretation</b><p>These charts are within-person exploratory trends. Compare broadly similar workouts and use the treadmill/outdoor filter when conditions materially differ. Missing values remain missing rather than being imputed, and “not detected” is not treated as zero.</p></div></>}
 </section>}
 </>}

function App(){
 const[page,setPage]=useState(pageFromLocation);
 const go=(next)=>{const path=pagePaths[next]||'/';if(window.location.pathname!==path)window.history.pushState({page:next},'',path);setPage(next);window.scrollTo({top:0,behavior:'auto'})};
 useEffect(()=>{const onPop=()=>setPage(pageFromLocation());window.addEventListener('popstate',onPop);return()=>window.removeEventListener('popstate',onPop)},[]);
 useEffect(()=>{const meta=pageMeta[page]||pageMeta.home;document.title=meta.title;let d=document.querySelector('meta[name="description"]');if(d)d.setAttribute('content',meta.description);let c=document.querySelector('link[rel="canonical"]');if(c)c.setAttribute('href','https://endurance-forge.com'+(pagePaths[page]||'/'));let og=document.querySelector('meta[property="og:url"]');if(og)og.setAttribute('content','https://endurance-forge.com'+(pagePaths[page]||'/'));},[page]);
 const body=page==='home'?<Home go={go}/>:page==='analyze'?<Analyze/>:page==='compare'?<Compare/>:page==='experimental'?<Experimental/>:page==='guide'?<MetricsGuide/>:page==='method'?<Methodology/>:<ScientificBasis/>;
 return <Shell page={page} go={go}>{body}</Shell>
}
createRoot(document.getElementById('root')).render(<App/>);
